//! Orders produced by the TypeScript SDK must pass the matcher's lot checks.
//! The fixture is regenerated by `packages/sdk/test/order.test.ts`.

use blindbook_core::intent::{check_lot, parse_rfc3339_ns, LotSpec};
use blindbook_core::Side;
use serde_json::Value;

fn fixture() -> Value {
    let path = format!("{}/tests/fixtures/sdk_orders.json", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn check_order(fx: &Value, key: &str, side: Side) -> usize {
    let order = &fx[key];
    let lot: u128 = fx["market"]["lot"].as_str().unwrap().parse().unwrap();
    let owner = order["owner"].as_str().unwrap();
    let spec = LotSpec {
        verifier: fx["verifier"].as_str().unwrap(),
        owner,
        base: fx["market"]["base"].as_str().unwrap(),
        quote: fx["market"]["quote"].as_str().unwrap(),
        lot,
        side,
    };
    let lots = order["lots"].as_array().unwrap();
    for l in lots {
        let checked = check_lot(&l["intent"], &spec).unwrap_or_else(|e| panic!("{key} lot rejected: {e}"));
        let limit: u128 = l["limit_quote"].as_str().unwrap().parse().unwrap();
        assert_eq!(checked.limit_quote, limit);
        assert_eq!(checked.signer_id, owner);
        assert_eq!(checked.deadline_ns, parse_rfc3339_ns("2030-01-01T00:00:00Z").unwrap());
    }
    lots.len()
}

#[test]
fn sdk_nep413_sell_lots_validate() {
    assert_eq!(check_order(&fixture(), "sell", Side::Sell), 2);
}

#[test]
fn sdk_erc191_buy_lots_validate() {
    assert_eq!(check_order(&fixture(), "buy", Side::Buy), 1);
}

#[test]
fn sdk_lots_are_refused_on_the_wrong_side() {
    let fx = fixture();
    let order = &fx["sell"];
    let spec = LotSpec {
        verifier: "intents.near",
        owner: order["owner"].as_str().unwrap(),
        base: fx["market"]["base"].as_str().unwrap(),
        quote: fx["market"]["quote"].as_str().unwrap(),
        lot: fx["market"]["lot"].as_str().unwrap().parse().unwrap(),
        side: Side::Buy,
    };
    assert!(check_lot(&order["lots"][0]["intent"], &spec).is_err());
}
